--Miss bet setting
INSERT INTO Dep_CustBetSetting_Member ([CustID], [SportType], [BetType], [MinBet], [MaxBet], [MaxPerMatch])
SELECT a.CustID, 9908 AS SportType, a.BetType, a.MinBet, a.MaxBet, a.MaxPerMatch
FROM Dep_CustBetSetting_Member a WITH (NOLOCK)
WHERE custid IN (25514918,31795296,40444817,40573173,41285462,48869270,49476247,53119609,54191957,54464102,54714588,55683583,55710377,56008886,57443026,57928013,58863084,58880138,59271701,60109134,62691285,64155335,64203875,64931338,65223170,65608681,65677727,65943953,66654579,67222559,67546274,67737625,70074777,72012980,73350648,73666005,73944009,74044451,75212913,76451038)
AND SportType in (180)
GO

--Wrong bet setting
