CROSS APPLY (SELECT t.MinBet, t.MaxBet, t.MaxPerMatch
			 FROM Dep_CustBetSetting_Member t WITH (NOLOCK)
			 WHERE t.CustID=d.CustID AND t.SportType=180) t
